class Zeugnis:
    def __init__(self, noten):
        self.noten = noten

    def schnitt(self):
        return sum(self.noten) / len(self.noten)

class HtmlFormat:
    def formatiere(self, z):
        s = z.schnitt()
        return f"<p>Schnitt {s:.2f}</p>"

z = Zeugnis([1, 2, 2, 3])
print(HtmlFormat().formatiere(z))
# <p>Schnitt 2.00</p>

class Tarif:
    def preis(self, basis):
        return basis

class Schueler(Tarif):
    def preis(self, basis):
        return basis * 0.5

class Senior(Tarif):
    def preis(self, basis):
        return basis * 0.7

for t in [Tarif(), Schueler(), Senior()]:
    print(t.preis(10))
# 10
# 5.0
# 7.0

class Rechteck:
    def __init__(self, b, h):
        self.b, self.h = b, h
    def setze_breite(self, b):
        self.b = b
    def flaeche(self):
        return self.b * self.h

class Quadrat(Rechteck):
    def __init__(self, a):
        super().__init__(a, a)
    def setze_breite(self, b):
        self.b = self.h = b

def test(r):
    r.setze_breite(5)
    return r.flaeche()

print(test(Rechteck(2, 4)))  # 20
print(test(Quadrat(4)))      # 25 (!)

from abc import ABC, abstractmethod

class Speicher(ABC):
    @abstractmethod
    def sichern(self, text): ...

class DateiSpeicher(Speicher):
    def sichern(self, text):
        print("Datei:", text)

class TestSpeicher(Speicher):
    def __init__(self):
        self.daten = []
    def sichern(self, text):
        self.daten.append(text)

class Notenservice:
    def __init__(self, speicher: Speicher):
        self.speicher = speicher
    def eintragen(self, name, note):
        self.speicher.sichern(f"{name};{note}")

Notenservice(DateiSpeicher()).eintragen("Ana", 1)
t = TestSpeicher()
Notenservice(t).eintragen("Ben", 2)
print(t.daten)
# Datei: Ana;1
# ['Ben;2']

